/* From Uiverse.io by joe-watson-sbf - Tags: input, search */
.__UIV_SCOPE__ .search {
  display: flex;
  align-items: center;
  justify-content: space-between;
  text-align: center;
}

.__UIV_SCOPE__ .search__input {
  font-family: inherit;
  font-size: inherit;
  background-color: #f4f2f2;
  border: none;
  color: #646464;
  padding: 0.7rem 1rem;
  border-radius: 30px;
  width: 12em;
  transition: all ease-in-out .5s;
  margin-right: -2rem;
}

.__UIV_SCOPE__ .search__input:hover, .__UIV_SCOPE__ .search__input:focus {
  box-shadow: 0 0 1em #00000013;
}

.__UIV_SCOPE__ .search__input:focus {
  outline: none;
  background-color: #f0eeee;
}

.__UIV_SCOPE__ .search__input::-webkit-input-placeholder {
  font-weight: 100;
  color: #ccc;
}

.__UIV_SCOPE__ .search__input:focus + .search__button {
  background-color: #f0eeee;
}

.__UIV_SCOPE__ .search__button {
  border: none;
  background-color: #f4f2f2;
  margin-top: .1em;
}

.__UIV_SCOPE__ .search__button:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .search__icon {
  height: 1.3em;
  width: 1.3em;
  fill: #b4b4b4;
}
